<?php
use App\Http\Controllers\{AuthenticatedSessionController,DashboardController,ScheduleController,UserController}; use Illuminate\Support\Facades\Route;
Route::middleware('guest')->group(function(){Route::get('/login',[AuthenticatedSessionController::class,'create'])->name('login');Route::post('/login',[AuthenticatedSessionController::class,'store'])->name('login.store');});
Route::middleware('auth')->group(function(){Route::post('/logout',[AuthenticatedSessionController::class,'destroy'])->name('logout');Route::get('/',[DashboardController::class,'index'])->name('dashboard');Route::view('/calendar','calendar')->name('calendar');Route::get('/events',[ScheduleController::class,'events'])->name('events');Route::middleware('admin')->group(function(){Route::resource('schedules',ScheduleController::class)->except('show');Route::resource('users',UserController::class)->only(['index','create','store','edit','update','destroy']);});Route::get('/schedule-details/{schedule}',[ScheduleController::class,'show'])->name('schedules.show');});
